import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import {
    Package, ShoppingCart, DollarSign, Users, Truck,
    AlertTriangle, TrendingUp, Clock, CheckCircle,
    BarChart3
} from 'lucide-react';
import adminService from '../../services/adminService.js';
import StatusBadge from '../../components/datadisplay/StatusBadge';
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip,
    ResponsiveContainer, PieChart, Pie, Cell, LineChart, Line,
    Legend
} from 'recharts';

const COLORS = ['#4F46E5', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899'];

const AdminOverview = () => {
    const { data, isLoading } = useQuery({
        queryKey: ['admin-dashboard'],
        queryFn: adminService.getDashboardStats
    });

    const stats = data?.stats;
    const ordersByStatus = data?.ordersByStatus || [];
    const topProducts = data?.topSellingProducts || [];
    const recentOrders = data?.recentOrders || [];

    const statCards = [
        {
            label: 'Total Orders',
            value: stats?.totalOrders || 0,
            icon: ShoppingCart,
            color: 'indigo',
            change: '+12%'
        },
        {
            label: 'Total Revenue',
            value: `$${(stats?.totalRevenue || 0).toLocaleString()}`,
            icon: DollarSign,
            color: 'emerald',
            change: '+8%'
        },
        {
            label: 'Active Products',
            value: stats?.totalProducts || 0,
            icon: Package,
            color: 'teal',
            alert: stats?.lowStockProducts > 0 ? `${stats?.lowStockProducts} low stock` : null
        },
        {
            label: 'Sales Reps',
            value: stats?.totalSalesReps || 0,
            icon: Users,
            color: 'amber'
        },
        {
            label: 'Dispatch Partners',
            value: stats?.totalDispatchPartners || 0,
            icon: Truck,
            color: 'purple'
        },
        {
            label: 'Pending Orders',
            value: stats?.pendingOrders || 0,
            icon: Clock,
            color: 'rose',
            alert: stats?.pendingOrders > 10 ? 'Needs attention' : null
        },
        {
            label: "Today's Orders",
            value: stats?.todayOrders || 0,
            icon: TrendingUp,
            color: 'cyan'
        },
        {
            label: 'Conversion Rate',
            value: `${stats?.conversionRate || 0}%`,
            icon: CheckCircle,
            color: 'blue'
        },
    ];

    const colorVariants = {
        indigo: 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400',
        emerald: 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400',
        teal: 'bg-teal-100 text-teal-600 dark:bg-teal-900/30 dark:text-teal-400',
        amber: 'bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400',
        rose: 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400',
        purple: 'bg-purple-100 text-purple-600 dark:bg-purple-900/30 dark:text-purple-400',
        cyan: 'bg-cyan-100 text-cyan-600 dark:bg-cyan-900/30 dark:text-cyan-400',
        blue: 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400',
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
                    Admin Dashboard
                </h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">
                    Overview of your business performance
                </p>
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                {statCards.map((card, index) => (
                    <motion.div
                        key={card.label}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: index * 0.05 }}
                        className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-200 dark:border-gray-700"
                    >
                        {isLoading ? (
                            <div className="animate-pulse space-y-3">
                                <div className="h-10 w-10 bg-gray-200 dark:bg-gray-700 rounded-lg" />
                                <div className="h-4 w-20 bg-gray-200 dark:bg-gray-700 rounded" />
                                <div className="h-8 w-28 bg-gray-200 dark:bg-gray-700 rounded" />
                            </div>
                        ) : (
                            <>
                                <div className="flex items-center justify-between mb-3">
                                    <div className={`p-2.5 rounded-lg ${colorVariants[card.color]}`}>
                                        <card.icon className="h-5 w-5" />
                                    </div>
                                    {card.change && (
                                        <span className="text-xs font-medium text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">
                                            {card.change}
                                        </span>
                                    )}
                                </div>
                                <p className="text-sm text-gray-500 dark:text-gray-400">{card.label}</p>
                                <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{card.value}</p>
                                {card.alert && (
                                    <p className="text-xs text-amber-600 mt-1 flex items-center gap-1">
                                        <AlertTriangle className="h-3 w-3" />
                                        {card.alert}
                                    </p>
                                )}
                            </>
                        )}
                    </motion.div>
                ))}
            </div>

            {/* Charts Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Orders by Status */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6"
                >
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                        Orders by Status
                    </h3>
                    <ResponsiveContainer width="100%" height={300}>
                        <PieChart>
                            <Pie
                                data={ordersByStatus}
                                cx="50%"
                                cy="50%"
                                innerRadius={60}
                                outerRadius={100}
                                paddingAngle={5}
                                dataKey="count"
                                nameKey="status"
                            >
                                {ordersByStatus.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                ))}
                            </Pie>
                            <Tooltip />
                            <Legend />
                        </PieChart>
                    </ResponsiveContainer>
                </motion.div>

                {/* Top Selling Products */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6"
                >
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                        Top Selling Products
                    </h3>
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={topProducts}>
                            <CartesianGrid strokeDasharray="3 3" />
                            <XAxis dataKey="name" />
                            <YAxis />
                            <Tooltip />
                            <Bar dataKey="orderCount" fill="#4F46E5" name="Orders" />
                        </BarChart>
                    </ResponsiveContainer>
                </motion.div>
            </div>

            {/* Recent Orders */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700"
            >
                <div className="p-6 border-b border-gray-200 dark:border-gray-700">
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                        Recent Orders
                    </h3>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full">
                        <thead>
                            <tr className="border-b border-gray-200 dark:border-gray-700">
                                <th className="text-left px-6 py-3 text-xs font-medium text-gray-500 uppercase">Order ID</th>
                                <th className="text-left px-6 py-3 text-xs font-medium text-gray-500 uppercase">Product</th>
                                <th className="text-left px-6 py-3 text-xs font-medium text-gray-500 uppercase">Customer</th>
                                <th className="text-left px-6 py-3 text-xs font-medium text-gray-500 uppercase">Status</th>
                                <th className="text-right px-6 py-3 text-xs font-medium text-gray-500 uppercase">Amount</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                            {recentOrders.map((order) => (
                                <tr key={order.id} className="hover:bg-gray-50 dark:hover:bg-gray-750">
                                    <td className="px-6 py-4 text-sm font-mono text-gray-500">
                                        #{order.id.slice(0, 8)}
                                    </td>
                                    <td className="px-6 py-4 text-sm text-gray-900 dark:text-white">
                                        {order.productName}
                                    </td>
                                    <td className="px-6 py-4 text-sm text-gray-500">
                                        {order.customerName}
                                    </td>
                                    <td className="px-6 py-4">
                                        <StatusBadge status={order.status} size="sm" />
                                    </td>
                                    <td className="px-6 py-4 text-sm font-medium text-right">
                                        ${order.totalAmount.toFixed(2)}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </motion.div>
        </div>
    );
};

export default AdminOverview;
